#include <bits/stdc++.h>
using namespace std;

// Order-statistic treap keyed by (timestamp, receiving order); node index = receiving order.
const int MAXN = 1000005;
long long ts[MAXN], logId[MAXN];
unsigned long long pri[MAXN];
int lc[MAXN], rc[MAXN], sz[MAXN];
int root = 0, nodes = 0;

unsigned long long splitmix(unsigned long long z) {
    z += 0x9E3779B97F4A7C15ULL;
    z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ULL;
    z = (z ^ (z >> 27)) * 0x94D049BB133111EBULL;
    return z ^ (z >> 31);
}

void pull(int x) { sz[x] = 1 + sz[lc[x]] + sz[rc[x]]; }

int rotateRight(int x) {
    int c = lc[x];
    lc[x] = rc[c], rc[c] = x;
    pull(x), pull(c);
    return c;
}

int rotateLeft(int x) {
    int c = rc[x];
    rc[x] = lc[c], lc[c] = x;
    pull(x), pull(c);
    return c;
}

int insert(int t, int node) {
    if (!t) return node;
    // A newer node with an equal timestamp goes right: ties keep receiving order.
    if (ts[node] < ts[t]) {
        lc[t] = insert(lc[t], node);
        if (pri[lc[t]] < pri[t]) t = rotateRight(t);
    } else {
        rc[t] = insert(rc[t], node);
        if (pri[rc[t]] < pri[t]) t = rotateLeft(t);
    }
    pull(t);
    return t;
}

// Number of logs with timestamp < bound.
int countLess(long long bound) {
    int node = root, c = 0;
    while (node) {
        if (ts[node] < bound) c += sz[lc[node]] + 1, node = rc[node];
        else node = lc[node];
    }
    return c;
}

// Appends the nodes with in-order rank in [first, last) of the subtree at node.
void collect(int node, int first, int last, int base, vector<int> &out) {
    if (!node || first >= last) return;
    int position = base + sz[lc[node]];
    if (first < position) collect(lc[node], first, min(last, position), base, out);
    if (first <= position && position < last) out.push_back(node);
    if (last > position + 1) collect(rc[node], max(first, position + 1), last, position + 1, out);
}

static vector<char> ibuf;
size_t ilen, ipos;

char *nextToken(size_t &len) {
    while (ipos < ilen && ibuf[ipos] <= ' ') ipos++;
    size_t s = ipos;
    while (ipos < ilen && ibuf[ipos] > ' ') ipos++;
    len = ipos - s;
    return ibuf.data() + s;
}

long long nextLong() {
    size_t len;
    char *t = nextToken(len);
    return strtoll(string(t, len).c_str(), nullptr, 10);
}

int main() {
    char chunk[1 << 16];
    size_t got;
    while ((got = fread(chunk, 1, sizeof(chunk), stdin)) > 0) ibuf.insert(ibuf.end(), chunk, chunk + got);
    ilen = ibuf.size();
    int limit = nextLong(), q = nextLong();
    bool hasMax = false;
    long long maxTs = 0;
    string out;
    vector<int> selected;
    for (int i = 0; i < q; i++) {
        size_t len;
        char *op = nextToken(len);
        if (op[0] == 'R') {
            long long id = nextLong(), t = nextLong();
            int node = ++nodes;
            ts[node] = t, logId[node] = id, pri[node] = splitmix(node), sz[node] = 1;
            root = insert(root, node);
            if (!hasMax || t > maxTs) maxTs = t, hasMax = true;
            continue;
        }
        // Window = timestamps in (maxTs - 3600, maxTs], as a rank range [left, right).
        int left = 0, right = 0;
        if (hasMax) left = countLess(maxTs - 3600 + 1), right = countLess(maxTs + 1);
        if (op[0] == 'G') {
            selected.clear();
            collect(root, max(left, right - limit), right, 0, selected);
            for (size_t k = 0; k < selected.size(); k++) {
                if (k) out += ',';
                out += to_string(logId[selected[k]]);
            }
            out += '\n';
        } else {
            out += to_string(right - left) + "\n";
        }
    }
    fwrite(out.data(), 1, out.size(), stdout);
}

