public class Main {
    // Order-statistic treap keyed by (timestamp, receiving order); node index = receiving order.
    static long[] ts, logId, pri;
    static int[] lc, rc, sz;
    static int root = 0;

    static long splitmix(long z) {
        z += 0x9E3779B97F4A7C15L;
        z = (z ^ (z >>> 30)) * 0xBF58476D1CE4E5B9L;
        z = (z ^ (z >>> 27)) * 0x94D049BB133111EBL;
        return z ^ (z >>> 31);
    }

