        int c = lc[x];
        lc[x] = rc[c];
        rc[c] = x;
        pull(x);
        pull(c);
        return c;
    }

    static int rotateLeft(int x) {
        int c = rc[x];
        rc[x] = lc[c];
        lc[c] = x;
        pull(x);
        pull(c);
        return c;
    }

    static int insert(int t, int node) {
        if (t == 0) return node;
        // A newer node with an equal timestamp goes right: ties keep receiving order.
        if (ts[node] < ts[t]) {
            lc[t] = insert(lc[t], node);
            if (Long.compareUnsigned(pri[lc[t]], pri[t]) < 0) t = rotateRight(t);
        } else {
            rc[t] = insert(rc[t], node);
            if (Long.compareUnsigned(pri[rc[t]], pri[t]) < 0) t = rotateLeft(t);
        }
        pull(t);
        return t;
    }

    // Number of logs with timestamp < bound.
    static int countLess(long bound) {
        int node = root, c = 0;
        while (node != 0) {
            if (ts[node] < bound) {
                c += sz[lc[node]] + 1;
                node = rc[node];
            } else node = lc[node];
        }
        return c;
    }

    // Appends the log ids with in-order rank in [first, last) of the subtree at node.
    static void collect(int node, int first, int last, int base, StringBuilder out) {
        if (node == 0 || first >= last) return;
        int position = base + sz[lc[node]];
        if (first < position) collect(lc[node], first, Math.min(last, position), base, out);
        if (first <= position && position < last) {
            if (out.length() > 0) out.append(',');
            out.append(logId[node]);
        }
        if (last > position + 1) collect(rc[node], Math.max(first, position + 1), last, position + 1, out);
    }

    static byte[] buf;
    static int pos;

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static byte nextOp() {
        while (buf[pos] <= ' ') pos++;
        byte c = buf[pos];
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return c;
    }

