            if (op == 'R') {
                long id = nextLong(), t = nextLong();
                int node = ++nodes;
                ts[node] = t;
                logId[node] = id;
                pri[node] = splitmix(node);
                sz[node] = 1;
                root = insert(root, node);
                if (!hasMax || t > maxTs) {
                    maxTs = t;
                    hasMax = true;
                }
                continue;
            }
            // Window = timestamps in (maxTs - 3600, maxTs], as a rank range [left, right).
            int left = 0, right = 0;
            if (hasMax) {
                left = countLess(maxTs - 3600 + 1);
                right = countLess(maxTs + 1);
            }
            if (op == 'G') {
                line.setLength(0);
                collect(root, Math.max(left, right - limit), right, 0, line);
                out.append(line).append('\n');
            } else {
                out.append(right - left).append('\n');
            }
        }
        System.out.print(out);
    }
