package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

// Order-statistic treap keyed by (timestamp, receiving order); node index = receiving order.
var ts, logID []int64
var pri []uint64
var lc, rc, sz []int
var root int

func splitmix(z uint64) uint64 {
	z += 0x9E3779B97F4A7C15
	z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9
	z = (z ^ (z >> 27)) * 0x94D049BB133111EB
	return z ^ (z >> 31)
}

func pull(x int) { sz[x] = 1 + sz[lc[x]] + sz[rc[x]] }

func rotateRight(x int) int {
	c := lc[x]
	lc[x], rc[c] = rc[c], x
	pull(x)
	pull(c)
	return c
}

func rotateLeft(x int) int {
	c := rc[x]
	rc[x], lc[c] = lc[c], x
	pull(x)
	pull(c)
	return c
}

func insert(t, node int) int {
	if t == 0 {
		return node
	}
	// A newer node with an equal timestamp goes right: ties keep receiving order.
	if ts[node] < ts[t] {
		lc[t] = insert(lc[t], node)
		if pri[lc[t]] < pri[t] {
			t = rotateRight(t)
		}
	} else {
		rc[t] = insert(rc[t], node)
		if pri[rc[t]] < pri[t] {
			t = rotateLeft(t)
		}
	}
	pull(t)
	return t
}

// countLess returns the number of logs with timestamp < bound.
func countLess(bound int64) int {
	node, c := root, 0
	for node != 0 {
		if ts[node] < bound {
			c += sz[lc[node]] + 1
			node = rc[node]
		} else {
			node = lc[node]
		}
	}
	return c
}

// collect appends the nodes with in-order rank in [first, last) of the subtree at node.
func collect(node, first, last, base int, out []int) []int {
	if node == 0 || first >= last {
		return out
	}
	position := base + sz[lc[node]]
	if first < position {
		out = collect(lc[node], first, min(last, position), base, out)
	}
	if first <= position && position < last {
		out = append(out, node)
	}
	if last > position+1 {
		out = collect(rc[node], max(first, position+1), last, position+1, out)
	}
	return out
}

func main() {
	data, _ := io.ReadAll(bufio.NewReaderSize(os.Stdin, 1<<20))
	pos := 0
	nextToken := func() []byte {
		for data[pos] <= ' ' {
			pos++
		}
		s := pos
		for pos < len(data) && data[pos] > ' ' {
			pos++
		}
		return data[s:pos]
	}
	nextInt := func() int64 {
		v, _ := strconv.ParseInt(string(nextToken()), 10, 64)
		return v
	}
	limit, q := int(nextInt()), int(nextInt())
	ts = make([]int64, q+1)
	logID = make([]int64, q+1)
	pri = make([]uint64, q+1)
	lc = make([]int, q+1)
	rc = make([]int, q+1)
	sz = make([]int, q+1)
	nodes := 0
	hasMax := false
	var maxTs int64
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	selected := []int{}
	for i := 0; i < q; i++ {
		op := nextToken()[0]
		if op == 'R' {
			id, t := nextInt(), nextInt()
			nodes++
			node := nodes
			ts[node], logID[node], pri[node], sz[node] = t, id, splitmix(uint64(node)), 1
			root = insert(root, node)
			if !hasMax || t > maxTs {
				maxTs, hasMax = t, true
			}
			continue
		}
		// Window = timestamps in (maxTs - 3600, maxTs], as a rank range [left, right).
		left, right := 0, 0
		if hasMax {
			left, right = countLess(maxTs-3600+1), countLess(maxTs+1)
		}
		if op == 'G' {
			selected = collect(root, max(left, right-limit), right, 0, selected[:0])
			for k, node := range selected {
				if k > 0 {
					w.WriteByte(',')
				}
				w.WriteString(strconv.FormatInt(logID[node], 10))
			}
			w.WriteByte('\n')
		} else {
			w.WriteString(strconv.Itoa(right-left) + "\n")
		}
	}
}
